"""Writes paper/tables/regions.tex and paper/tables/subgroups.tex from results/*.json."""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__)); RES = os.path.join(HERE, "..", "results"); OUT = os.path.join(HERE, "..", "paper", "tables")
cl = {r["cluster"]: r for r in json.load(open(os.path.join(RES, "clusters.json")))}
cap = json.load(open(os.path.join(RES, "capalibag.json")))
mo = json.load(open(os.path.join(RES, "models.json")))["core: original 3-way"]
coremed = dict(mo["weights"]); coremed = {"byz": coremed["Byzantine Anatolia"], "tur": coremed["Medieval Turkic (Kazakhstan, Kyrgyzstan)"], "kar": coremed["Kartvelian (Georgian, Laz)"], "fit": round(mo["fit"], 2)}
NAME = {"Core Anatolia": "Core Anatolia", "West Anatolia": "West", "Central Anatolia": "Central", "North Anatolia (western Black Sea)": "North (W. Black Sea)", "South (Adana, Mersin, Gaziantep)": "South", "Trabzon, Rize, Artvin": "Trabzon, Rize, Artvin", "Erzurum and the east": "Erzurum and the east", "Balkan Turks": "Balkan Turks", "Azerbaijani": "Azerbaijanis (Caucasus)"}
f = lambda x: f"{x:.1f}"
L = ["% Generated by analysis/12_paper_tables.py.", "\\begin{tabular}{@{}l rrrr @{\\hspace{10pt}} rrrr @{\\hspace{10pt}} rrrr@{}}", "\\toprule",
     " & \\multicolumn{4}{c}{Medieval Turkic (650--1200)} & \\multicolumn{4}{c}{Çapalıbağ (1300--1650)} & \\multicolumn{4}{c}{Kaman-Kalehöyük (Ottoman)} \\\\",
     "\\cmidrule(lr){2-5}\\cmidrule(lr){6-9}\\cmidrule(l){10-13}", "Target & Byz & Tur & Kar & Fit & Byz & Çap & Kar & Fit & Byz & Ott & Kar & Fit \\\\", "\\midrule"]
for r in cap:
    m = coremed if r["cluster"] == "Core Anatolia" else cl[r["cluster"]]
    L.append(f"{NAME[r['cluster']]} & {f(m['byz'])} & {f(m['tur'])} & {f(m['kar'])} & {m['fit']:.2f} & {f(r['byz'])} & {f(r['cap'])} & {f(r['kar'])} & {r['fit']:.2f} & {f(r['otm_byz'])} & {f(r['otm'])} & {f(r['otm_kar'])} & {r['otm_fit']:.2f} \\\\")
L += ["\\bottomrule", "\\end{tabular}"]
open(os.path.join(OUT, "regions.tex"), "w").write("\n".join(L) + "\n")
sub = json.load(open(os.path.join(RES, "subgroups.json")))
esc = lambda s: s.replace("&", "\\&").replace("%", "\\%")
half = (len(sub) + 1) // 2
L = ["% Generated by analysis/12_paper_tables.py.", "\\begin{tabular}{@{}lrrrrr@{\\hspace{14pt}}lrrrrr@{}}", "\\toprule",
     "Subgroup & $n$ & Tur & Çap & Ott & Fit & Subgroup & $n$ & Tur & Çap & Ott & Fit \\\\", "\\midrule"]
cell = lambda r: f"{esc(r['label'].replace(' (Anatolian Turk Profile)', ' (Anat.)').replace(' (Anatolian Turk-Mixed Profile)', ' (mixed)').replace(' (Anatolian Turk-Mixed Balkan Turk Profile)', ' (mixed)').replace('Canakkale Biga Peninsula', 'Canakkale Biga'))} & {r['n']} & {r['tur']:.0f} & {r['cap']:.0f} & {r['otm']:.0f} & {min(r['tur_fit'], r['cap_fit'], r['otm_fit']):.2f}"
for i in range(half):
    a = cell(sub[i]); b = cell(sub[i + half]) if i + half < len(sub) else " & & & & & "
    L.append(f"{a} & {b} \\\\")
L += ["\\bottomrule", "\\end{tabular}"]
open(os.path.join(OUT, "subgroups.tex"), "w").write("\n".join(L) + "\n")
print("wrote tables/regions.tex, tables/subgroups.tex,", len(sub), "subgroups")
